/**
 * Layout gate: every screen, at the smallest and largest supported iPhones
 * and an iPad, with a busy seller's real server-shaped data
 * (fixtures.json is generated by backend/tests/test_ui_fixtures.py).
 *
 * Fails if anything spills past the screen edge or the page scrolls sideways.
 * Screenshots land in test-results/visual/ for review.
 */
import { expect, test, type Page } from '@playwright/test';
import fixtures from './fixtures.json';

const SIZES = [
  { name: 'iphone-se', width: 375, height: 667 },
  { name: 'iphone-15', width: 393, height: 852 },
  { name: 'iphone-pro-max', width: 430, height: 932 },
  { name: 'ipad', width: 820, height: 1180 },
];

const SCREENS: {
  name: string;
  path: string;
  ready?: string;
  authed?: boolean;
  /** Text of controls to tap, in order, before the screenshot. */
  steps?: string[];
  fullPage?: boolean;
}[] = [
  { name: 'login', path: '/login', authed: false },
  { name: 'register', path: '/register', authed: false },
  { name: 'forgot-password', path: '/forgot-password', authed: false },
  { name: 'dashboard', path: '/dashboard' },
  { name: 'inventory', path: '/inventory', ready: 'Nike Dunk Low' },
  { name: 'item-detail', path: `/inventory/${fixtures.item_id}`, ready: 'Nike Dunk Low' },
  { name: 'add', path: '/inventory/add', ready: 'Scan a box' },
  { name: 'edit', path: `/inventory/edit?id=${fixtures.item_id}` },
  { name: 'sale', path: '/inventory/sale' },
  { name: 'sale-cart', path: `/inventory/sale?add=${fixtures.item_id}`, ready: 'Cart · 1 item' },
  { name: 'invoices', path: '/inventory/invoices' },
  { name: 'invoice-preview', path: `/inventory/invoice-preview?id=${fixtures.invoice_id}`, ready: 'Marcus Reed', fullPage: true },
  {
    name: 'invoice-record-payment',
    path: '/inventory/invoices',
    ready: 'Recent Invoices',
    steps: ['Recent Invoices', 'Open Invoice', 'Record payment'],
    fullPage: true,
  },
  { name: 'import', path: '/inventory/import' },
  { name: 'more', path: '/more' },
  { name: 'settings', path: '/settings' },
  { name: 'subscription', path: '/settings/subscription' },
  { name: 'support', path: '/settings/support' },
  { name: 'sync-center', path: '/settings/sync-center' },
  { name: 'analytics', path: '/settings/analytics' },
  { name: 'show-summary', path: '/settings/show-summary', ready: 'Count the cash box' },
];

const ROUTES: [RegExp, unknown][] = [
  [/\/auth\/me$/, fixtures.me],
  [/\/dashboard\/advanced/, fixtures.advanced],
  [/\/dashboard\/show-summary/, fixtures.show_summary],
  [/\/dashboard$/, fixtures.dashboard],
  [/\/inventory\/[^/?]+\/activity/, fixtures.item_activity],
  [new RegExp(`/inventory/${fixtures.item_id}$`), fixtures.item],
  [/\/inventory(\?|$)/, fixtures.inventory],
  [/\/transactions(\?|$)/, fixtures.transactions],
  [new RegExp(`/invoices/${fixtures.invoice_id}$`), fixtures.invoice],
  [/\/invoices(\?|$)/, fixtures.invoices],
  [/\/features\/tiers/, fixtures.tiers],
  [/\/features$/, fixtures.features],
  [/\/subscriptions\/me/, fixtures.subscription],
  [/\/integrations\/health/, fixtures.integrations_health],
  [/\/health$/, { status: 'ok' }],
  [/\/scan\/memory/, []],
];

async function stubApi(page: Page) {
  await page.route('**/api/v1/**', (route) => {
    const path = new URL(route.request().url()).pathname + new URL(route.request().url()).search;
    const hit = ROUTES.find(([re]) => re.test(path.split('?')[0]) || re.test(path));
    return route.fulfill({
      status: 200,
      contentType: 'application/json',
      body: JSON.stringify(hit ? hit[1] : []),
    });
  });
}

/** Elements whose box extends past the viewport, ignoring sideways scrollers. */
async function overflowing(page: Page) {
  return page.evaluate(() => {
    const vw = window.innerWidth;
    const bad: string[] = [];
    const scrollsX = (el: Element | null): boolean => {
      for (let p = el?.parentElement; p; p = p.parentElement) {
        const ox = getComputedStyle(p).overflowX;
        if ((ox === 'auto' || ox === 'scroll') && p.scrollWidth > p.clientWidth) return true;
        if (ox === 'hidden' && p !== document.body && p !== document.documentElement) {
          const r = p.getBoundingClientRect();
          if (r.right <= vw + 1 && r.left >= -1) return true;
        }
      }
      return false;
    };
    for (const el of Array.from(document.querySelectorAll('body *'))) {
      const r = el.getBoundingClientRect();
      if (r.width === 0 || r.height === 0) continue;
      const style = getComputedStyle(el);
      if (style.visibility === 'hidden' || style.display === 'none' || style.position === 'fixed') continue;
      if ((r.right > vw + 1 || r.left < -1) && !scrollsX(el)) {
        const label = el.getAttribute('aria-label') || (el.textContent || '').trim().slice(0, 40);
        bad.push(`${el.tagName.toLowerCase()} [${Math.round(r.left)}..${Math.round(r.right)}] ${label}`);
      }
    }
    if (document.documentElement.scrollWidth > vw + 1) bad.push(`page scrolls sideways (${document.documentElement.scrollWidth}px)`);
    return bad.slice(0, 8);
  });
}

type Screen = (typeof SCREENS)[number];

async function openScreen(page: Page, screen: Screen, size: { width: number; height: number }) {
  await page.setViewportSize({ width: size.width, height: size.height });
  await stubApi(page);
  await page.goto('/');
  if (screen.authed !== false) {
    await page.evaluate(() => localStorage.setItem('vendora_access_token', 'demo'));
  } else {
    await page.evaluate(() => localStorage.clear());
  }
  await page.goto('/');
  // Navigating before the router has mounted leaves the app on its
  // start screen, so wait for it to settle and retry the push once.
  await page.waitForLoadState('networkidle');
  const navigate = () =>
    page.evaluate((p) => {
      window.history.pushState({}, '', p);
      window.dispatchEvent(new PopStateEvent('popstate'));
    }, screen.path);
  await navigate();
  if (screen.ready) {
    const ready = page.getByText(screen.ready).first();
    try {
      await expect(ready).toBeVisible({ timeout: 5_000 });
    } catch {
      await navigate();
      await expect(ready).toBeVisible();
    }
  }
  for (const step of screen.steps ?? []) {
    await page.getByText(step, { exact: true }).first().click();
    await page.waitForTimeout(250);
  }
  await page.waitForTimeout(700);
}

test.describe('layout gate', () => {
  for (const size of SIZES) {
    for (const screen of SCREENS) {
      test(`${screen.name} @ ${size.name}`, async ({ page }) => {
        test.skip(test.info().project.name !== 'iPhone 12', 'sizes are iterated inside the test');
        await openScreen(page, screen, size);
        await page.screenshot({
          path: `test-results/visual/${size.name}/${screen.name}.png`,
          fullPage: !!screen.fullPage,
        });
        expect(await overflowing(page), `${screen.name} overflows at ${size.width}px`).toEqual([]);
      });
    }
  }
});

/**
 * Dynamic Type stand-in. react-native-web ignores the OS text size, so scale
 * every element's computed font size (and px line height) by LARGE_TEXT,
 * the same as iOS "larger text" does to a Text. LARGE_TEXT matches
 * FONT_SCALE.chrome in theme/tokens.ts: text capped with maxFontSizeMultiplier
 * on device stops growing exactly there, so the web run is a faithful worst
 * case for capped chrome and a real large-size check for body copy.
 */
const LARGE_TEXT = 1.3;
const LARGE_TEXT_SCREENS = ['dashboard', 'inventory', 'item-detail', 'add', 'sale', 'sale-cart'];

async function scaleText(page: Page, factor: number) {
  await page.evaluate((k) => {
    const all = Array.from(document.querySelectorAll<HTMLElement>('body *'));
    // Read everything first so inherited sizes aren't scaled twice.
    const sizes = all.map((el) => {
      const cs = getComputedStyle(el);
      return { el, font: parseFloat(cs.fontSize), line: cs.lineHeight.endsWith('px') ? parseFloat(cs.lineHeight) : null };
    });
    for (const { el, font, line } of sizes) {
      if (!font) continue;
      el.style.fontSize = `${font * k}px`;
      if (line) el.style.lineHeight = `${line * k}px`;
    }
  }, factor);
  await page.waitForTimeout(300);
}

test.describe('layout gate: large text', () => {
  for (const size of SIZES.filter((s) => s.name !== 'ipad')) {
    for (const screen of SCREENS.filter((s) => LARGE_TEXT_SCREENS.includes(s.name))) {
      test(`${screen.name} @ ${size.name} @ ${LARGE_TEXT}x text`, async ({ page }) => {
        test.skip(test.info().project.name !== 'iPhone 12', 'sizes are iterated inside the test');
        await openScreen(page, screen, size);
        await scaleText(page, LARGE_TEXT);
        await page.screenshot({
          path: `test-results/visual/large-text/${size.name}/${screen.name}.png`,
          fullPage: !!screen.fullPage,
        });
        expect(await overflowing(page), `${screen.name} overflows at ${size.width}px with large text`).toEqual([]);
      });
    }
  }
});
